import{_ as t,a,c as n,ac as i}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第二册：实践与进步 · Lesson 68 Persistent","description":"学习 动名词与动词搭配，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 68 Persistent","description":"学习 动名词与动词搭配，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 动名词与动词搭配，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 67 Volcanoes","link":"/life/english/new-concept/book-2/unit-03/lesson-067"},"next":{"text":"第二册：实践与进步 · Lesson 69 But not murder!","link":"/life/english/new-concept/book-2/unit-03/lesson-069"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 67 Volcanoes","link":"/life/english/new-concept/book-2/unit-03/lesson-067"},"next":{"text":"第二册：实践与进步 · Lesson 69 But not murder!","link":"/life/english/new-concept/book-2/unit-03/lesson-069"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-03/lesson-068.md","filePath":"life/english/new-concept/book-2/unit-03/lesson-068.md"}'),o={name:"life/english/new-concept/book-2/unit-03/lesson-068.md"};function s(r,e,l,d,h,c){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="第二册-实践与进步-·-lesson-68-persistent" tabindex="-1">第二册：实践与进步 · Lesson 68 Persistent <a class="header-anchor" href="#第二册-实践与进步-·-lesson-68-persistent" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 68 Persistent&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-03/overview">单元 3</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>反复邀请会让忙碌的人感到压力，礼貌拒绝需要明确边界；练习动名词搭配。本课的语言观察是：insist on 后接动名词，avoid 后也接动名词但不加介词。两种动词都能接 -ing，不代表结构完全相同。完成学习后，请写三句礼貌回应坚持帮忙的人：感谢、解释、替代安排。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>insist</td><td>/ɪnˈsɪst/</td><td>v.</td><td>坚持</td><td>insist on paying</td></tr><tr><td>avoid</td><td>/əˈvɔɪd/</td><td>v.</td><td>避免</td><td>avoid making noise</td></tr><tr><td>persistent</td><td>/pəˈsɪstənt/</td><td>adj.</td><td>坚持不懈的</td><td>a persistent caller</td></tr><tr><td>busy</td><td>/ˈbɪzi/</td><td>adj.</td><td>忙碌的</td><td>a busy morning</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>insist on doing — 坚持做某事</li><li>avoid doing — 避免做某事，avoid 后不加 to</li></ul><h2 id="语法讲解-动名词与动词搭配" tabindex="-1">语法讲解：动名词与动词搭配 <a class="header-anchor" href="#语法讲解-动名词与动词搭配" aria-label="Permalink to &quot;语法讲解：动名词与动词搭配&quot;">​</a></h2><p>动词的 -ing 形式可像名词一样作主语或宾语，常出现在 enjoy、avoid、finish 等动词之后，以及介词之后。它仍能带自己的宾语或状语。另一些动词通常接 to 不定式，不能按中文意思随意互换；stop、remember、try 等词接两种形式时意思还可能改变。遇到 to 先判断它是不定式标记还是介词，再决定后面使用原形还是 -ing。本课应用：insist on 后接动名词，avoid 后也接动名词但不加介词。两种动词都能接 -ing，不代表结构完全相同。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>My neighbour insisted on helping me carry the boxes.</p></blockquote><p>邻居坚持要帮我搬箱子。</p><p>insisted on 是谓语搭配，helping 为介词宾语；help me carry 中 carry 可不带 to。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>insist to help 应改为 insist on helping；avoid to answer 应为 avoid answering。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>强调 thanked 与 explained 的并列，朗读 insisted 的 /ɪd/ 不漏音节。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>My neighbour insisted on helping me carry the boxes. I thanked her but explained that the boxes were empty. We agreed to meet for tea later.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写三句礼貌回应坚持帮忙的人：感谢、解释、替代安排。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：insisted on 是谓语搭配，helping 为介词宾语；help me carry 中 carry 可不带 to。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：insist to help 应改为 insist on helping；avoid to answer 应为 avoid answering。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填 help：She insisted on ___ me.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> helping</p><p><strong>解析：</strong> 介词 on 后接动名词。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>箱子为什么不需要额外帮助？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> They were empty.</p><p><strong>解析：</strong> 示范说明具体原因，不应猜测说话者讨厌邻居。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>改正：He avoided to answer the question。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> He avoided answering the question.</p><p><strong>解析：</strong> avoid 接动名词作宾语。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：动名词与动词搭配。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-03/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-03/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-03/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-067">上一课</a> · <a href="/life/english/new-concept/book-2/unit-03/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-03/lesson-069">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=t(o,[["render",s]]);export{u as __pageData,b as default};
